INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('sprouts', 'sprouts', 'Sprouts', 'AIIMS Flyover, New Delhi, India', 'https://www.vibhorsogani.com/work/sprouts', 'Standing 40 feet tall and spread across 6 acres of green space around the AIIMS flyover in the heart of Delhi, Sprouts is India''s largest site-specific public art installation...', '["Standing 40 feet tall and spread across 6 acres of green space around the AIIMS flyover in the heart of Delhi, Sprouts is India''s largest site-specific public art installation, a Delhi government initiative towards the beautification of the capital. The commission traces back to a brief given directly to Vibhor Sogani by then Chief Minister of Delhi, Sheila Dikshit: \"From walled city to world city.\" That single line became the seed for the entire project.","Working from that brief, Sogani developed Sprouts around the idea of seeds beginning to sprout, using stainless steel as a new-age material to represent India as a growing, contemporary nation. The wider objective was to create a civic landmark through a series of installations signifying growth, development, and progress — timed in part to the run-up to the 2010 Commonwealth Games, when Delhi was actively reshaping its public image for an international audience.","More than a decade on, the sprouts have outgrown their original brief. Set against the landscape, they register the changing moods of Delhi''s weather and have become one of the city''s most recognisable public memories — less a government beautification project now than a genuine landmark, cited alongside other icons as visual shorthand for the capital."]', '["/images/projects/sprouts/image_1.jpg","/images/projects/sprouts/image_2.JPG","/images/projects/sprouts/image_3.jpg","/images/projects/sprouts/image_4.jpg","/images/projects/sprouts/image_5.jpg","/images/projects/sprouts/image_6.png"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('pm_vishwakarma_installation', 'pm-vishwakarma-installation', 'PM Vishwakarma Installation', 'Yashobhoomi (IICC), New Delhi, India', 'https://www.vibhorsogani.com/work/pm-vishwakarma-installation', 'Installed at Yashobhoomi — the India International Convention and Expo Centre in Dwarka — this piece was commissioned as an aesthetic centrepiece for the venue''s launch...', '["Installed at Yashobhoomi — the India International Convention and Expo Centre in Dwarka — this piece was commissioned as an aesthetic centrepiece for the venue''s launch, crafted under the stewardship of the National Gallery of Modern Art, India. The launch itself was a major state occasion: Prime Minister Narendra Modi dedicated Yashobhoomi to the nation and unveiled the PM Vishwakarma Scheme for traditional artisans and craftspeople on 17 September 2023, on the occasion of Vishwakarma Jayanti.","Drawing on the form of the Ashoka Chakra, the installation depicts 24 hands in continuous motion — a visual language chosen to echo the scheme''s own subject, the skilled hands of India''s traditional workforce. The Vishwakarma scheme was framed by the government as recognition for artisans who work with their hands and tools, so Sogani''s piece sits in direct dialogue with the occasion it marks rather than as a generic commemorative object.","The work now stands alongside other Sogani installations that anchor major public and civic sites around Delhi — Sprouts near the AIIMS flyover, Mahatma on Satyagraha Marg, and Kalpataru on Motilal Nehru Marg — continuing a pattern in his practice of being entrusted with large-scale pieces tied to government-led national initiatives."]', '["/images/projects/pm_vishwakarma_installation/image_1.jpg","/images/projects/pm_vishwakarma_installation/image_2.jpg","/images/projects/pm_vishwakarma_installation/image_3.jpg","/images/projects/pm_vishwakarma_installation/image_4.jpg","/images/projects/pm_vishwakarma_installation/image_5.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('bodhi_tree', 'bodhi-tree', 'Bodhi Tree', 'Royal Caribbean Utopia of the Seas', 'https://www.vibhorsogani.com/work/bodhi-tree', 'Bodhi Tree is a nine-deck-high wishing-tree installation built into the elevator shafts of Royal Caribbean''s Utopia of the Seas...', '["Bodhi Tree is a nine-deck-high wishing-tree installation built into the elevator shafts of Royal Caribbean''s Utopia of the Seas, the sixth ship in the Oasis class and, by gross tonnage, the third largest cruise ship in the world. Studio Vibhor Sogani was commissioned by Royal Caribbean''s art curators at ArtLink to design the piece for the ship''s public spaces, working from his Delhi studio through the build process.","The sculpture is made of 31,446 hand-crafted stainless-steel spheres, assembled into a canopy form that draws on the sacred Bodhi tree of ancient lore — a tree traditionally associated with abundance, spiritual awakening, and the fulfilment of desires. The scale of the piece, spanning nine decks within the ship''s vertical shafts, meant the work had to be engineered as much as sculpted, with thousands of individual pieces fabricated and finished before installation.","Positioned in the elevator shafts, the tree is designed to be encountered vertically, in passing, over the course of a cruise rather than viewed all at once — an approach Sogani has described as aiming to capture the childlike wonder of discovery and revelation, inviting passengers to contemplate the relationship between matter and form each time they pass through the space."]', '["/images/projects/bodhi_tree/image_1.jpg","/images/projects/bodhi_tree/image_2.jpg","/images/projects/bodhi_tree/image_3.jpg","/images/projects/bodhi_tree/image_4.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('sangam', 'sangam', 'Sangam', 'Archaeological Museum, Vadnagar, Gujarat', 'https://www.vibhorsogani.com/work/sangam', 'Sangam stands in the Archaeological Experiential Museum at Vadnagar, Gujarat — a museum built at a cost of roughly ₹300 crore...', '["Sangam stands in the Archaeological Experiential Museum at Vadnagar, Gujarat — a museum built at a cost of roughly ₹300 crore around the 2,500-year-old excavated city, and inaugurated by Union Home Minister Amit Shah. Crafted in a mix of mirror-finish and antique, natural-finish stainless steel, the sculpture takes its name from the Hindi word for confluence, representing the meeting of the streams of culture, trade, and history that shaped the ancient settlement.","The surface treatment does the conceptual work here: convex and concave passages catch and distort light and reflection in different ways, evoking the weathered, layered texture of Vadnagar''s old city walls. Sogani has described the piece as intertwining past, present, and future — appropriate for a museum built around the idea that history and ongoing excavation coexist on the same site.","Sangam is part of a small suite of works Sogani made for the museum, alongside Pratibimb and Atmachintan, each occupying a different emotional register — Sangam opens the sequence with confluence, while Pratibimb closes it by turning the museum''s historical narrative back onto the viewer''s own reflected face."]', '["/images/projects/sangam/image_1.jpg","/images/projects/sangam/image_2.jpg","/images/projects/sangam/image_3.jpg","/images/projects/sangam/image_4.png"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('joy', 'joy', 'Joy', 'Dubai Creek Harbour, UAE', 'https://www.vibhorsogani.com/work/joy', 'Joy is a 30-foot-tall public art installation at Dubai Creek Harbour, commissioned as part of Art EMAAR''s outdoor gallery initiative...', '["Joy is a 30-foot-tall public art installation at Dubai Creek Harbour, commissioned as part of Art EMAAR''s outdoor gallery initiative and positioned near the Creek Marina, close to the site of the planned Dubai Creek Tower. Crafted in polished stainless steel, the sculpture takes the form of an oversized bouquet of balloons — a simple, immediately legible image scaled up to landmark size.","The piece is conceived as an ode to everything in life that is beautiful, joy-giving, and unadulterated, inspired by the uncomplicated happiness of a child taking pleasure in simple things. Its mirrored balloon surfaces reflect the surrounding environment and the passers-by themselves, so the work is never static — it changes with the light, the weather, and whoever happens to be walking past.","Emaar''s own framing describes it as a shimmering beacon capable of lifting a viewer out of the mundane, and in practice it functions as one of Dubai Creek Harbour''s welcoming markers — often the first artwork visitors encounter at the Creek Marina entrance, alongside other outdoor-gallery pieces like the Flower Tree and Musical Shadows."]', '["/images/projects/joy/image_1.jpg","/images/projects/joy/image_2.jpg","/images/projects/joy/image_3.jpg","/images/projects/joy/image_4.jpg","/images/projects/joy/image_5.jpg","/images/projects/joy/image_6.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('pratibimb', 'pratibimb', 'Pratibimb', 'Archaeological Museum, Vadnagar, Gujarat', 'https://www.vibhorsogani.com/work/pratibimb', 'Pratibimb — Hindi for "reflection" — is the third piece in Sogani''s suite of works for the Vadnagar Archaeological Experiential Museum...', '["Pratibimb — Hindi for \"reflection\" — is the third piece in Sogani''s suite of works for the Vadnagar Archaeological Experiential Museum, and the one designed to close the visitor''s journey through the space. Where Sangam opens the museum narrative with the idea of confluence, Pratibimb turns it back on the viewer: a large, blurred disc represents the vast, indistinct past, set against smaller convex and concave discs in mirror finish that stand for the present and future.","The sculpture is deliberately built to reflect the viewer''s own face back at them. After walking through galleries devoted to Vadnagar''s excavated history — its urban planning, trade, and governance across millennia — Pratibimb positions the visitor''s own reflection as the final \"exhibit,\" a quiet way of saying that the story of the past ultimately concludes in the present moment, standing in front of the work.","This use of mirror-polished steel as a literal reflective surface for the viewer runs through several of Sogani''s works — Nebula and Ensō use similar mirrored spheres — but at Vadnagar, the device is given a specific narrative job: closing out a museum experience organised around deep history by handing the ending back to whoever is standing there."]', '["/images/projects/pratibimb/image_1.jpg","/images/projects/pratibimb/image_2.png","/images/projects/pratibimb/image_3.jpg","/images/projects/pratibimb/image_4.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('mahatma', 'mahatma', 'Mahatma', 'Satyagraha Marg, New Delhi, India', 'https://www.vibhorsogani.com/work/mahatma', 'Mahatma was executed with support of the Ministry of Culture, Government of India and the National Gallery of Modern Art, India for the PARI (Public Art Project of India) initiative.', '["Mahatma was executed with support of the Ministry of Culture, Government of India and the National Gallery of Modern Art, India for the PARI (Public Art Project of India) initiative.","Mahatma is a stainless steel sculpture that draws inspiration from the life and legacy of Mahatma Gandhi, the father of the nation. It reflects on Gandhi''s unwavering commitment to truth and self-righteousness."]', '["/images/projects/mahatma/image_1.jpg","/images/projects/mahatma/image_2.jpg","/images/projects/mahatma/image_3.jpg","/images/projects/mahatma/image_4.jpg","/images/projects/mahatma/image_5.jpg","/images/projects/mahatma/image_6.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('map_vadnagar', 'map-vadnagar', 'Map Vadnagar', 'Vadnagar Museum, Gujarat, India', 'https://www.vibhorsogani.com/work/map-vadnagar', 'Also housed within the Vadnagar Archaeological Experiential Museum, this piece renders the historic city of Vadnagar as a physical map...', '["Also housed within the Vadnagar Archaeological Experiential Museum, this piece renders the historic city of Vadnagar as a physical map, worked in antique brass, antique copper, and stainless steel. Rather than a flat wall map, it marks out the settlement''s key historic points in relief and mixed metal finishes, giving visitors a tactile, sculptural way to orient themselves within a city whose excavated history stretches back more than 2,500 years.","Positioned within the same museum complex inaugurated by Amit Shah, the map complements Sogani''s other Vadnagar commissions — Sangam and Pratibimb — by grounding their more abstract, reflective ideas in an actual sense of place and geography.","The choice of three different metals is deliberate: each finish reads differently under light, letting the map distinguish between different eras or categories of historic site without relying on colour or printed labelling, in keeping with the material language Sogani uses across his practice."]', '["/images/projects/map_vadnagar/image_1.jpg","/images/projects/map_vadnagar/image_2.png","/images/projects/map_vadnagar/image_3.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('kalpavriksha', 'kalpavriksha', 'Kalpavriksha', 'Arvind Uplands, Ahmedabad, India', 'https://www.vibhorsogani.com/work/kalpavriksha', 'Kalpavriksha, the wish fulfilling tree has been portrayed as a symbol of eternal love, immortality and fertility in sacred texts and scriptures. Standing 35 feet tall at Arvind Uplands in Ahmedabad, India, this light sculpture is crafted using mirror-finished steel balls. The installation comes alive at night with a dynamic glow.', '[]', '["/images/projects/kalpavriksha/image_1.jpg","/images/projects/kalpavriksha/image_2.jpg","/images/projects/kalpavriksha/image_3.jpg","/images/projects/kalpavriksha/image_4.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('deepam', 'deepam', 'Deepam', 'Canals of Amsterdam, Netherlands', 'https://www.vibhorsogani.com/work/deepam', 'Inspired from the popular Indian festival of lights — Diwali, this light installation is composed of approximately 70 floating Deepams spread over 100m in the canal of Amsterdam. Made in brass, these handcrafted pieces feature controlled undulations that enhance and magnify the effect of the dancing amber flame inside. It invites viewers to partake in the spirit of Diwali and share its universal message of light and hope.', '[]', '["/images/projects/deepam/image_1.jpg","/images/projects/deepam/image_2.jpeg","/images/projects/deepam/image_3.jpeg","/images/projects/deepam/image_4.jpeg","/images/projects/deepam/image_5.jpg","/images/projects/deepam/image_6.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('peepal', 'peepal', 'Peepal', 'Tijara Fort Palace, Rajasthan, India', 'https://www.vibhorsogani.com/work/peepal', 'Peepal is a site-specific installation located at the Tijara Fort Palace in Rajasthan, India. The space housing this installation has been named "Vibhor Mahal". It is inspired by the ancient Hindu reverence for the inverted banyan tree which has its roots upwards and branches down and whose leaves are Vedic hymns.', '[]', '["/images/projects/peepal/image_1.jpg","/images/projects/peepal/image_2.jpg","/images/projects/peepal/image_3.jpg","/images/projects/peepal/image_4.jpg","/images/projects/peepal/image_5.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('through_the_depths', 'through-the-depths', 'Through the Depths', 'Studio Collection & Exhibitions', 'https://www.vibhorsogani.com/work/through-the-depths', 'Through the Depths is an ode to the process of transformation. This installation symbolises the journey of raw stone, extracted from the depths, which is then refined and polished into a timeless treasure.', '[]', '["/images/projects/through_the_depths/image_1.jpg","/images/projects/through_the_depths/image_2.jpg","/images/projects/through_the_depths/image_3.jpg","/images/projects/through_the_depths/image_4.jpg","/images/projects/through_the_depths/image_5.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('tidal_tango', 'tidal-tango', 'Tidal Tango', 'Studio Collection & Private Installations', 'https://www.vibhorsogani.com/work/tidal-tango', '"Tidal Tango" is a sculptural ode to the dynamic, yet symphonic, union of two waves. Crafted in mirror-finish Stainless steel, this piece distills the beauty of collision and convergence, inviting the viewer to contemplate the intersections of power, serenity, and the eternal ebb and flow of life.', '[]', '["/images/projects/tidal_tango/image_1.jpg","/images/projects/tidal_tango/image_2.jpg","/images/projects/tidal_tango/image_3.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('balancing_act', 'balancing-act', 'Balancing Act', 'Studio Collection & Architectural Works', 'https://www.vibhorsogani.com/work/balancing-act', 'Balancing Act is a series that captures the essence of a tightrope walk, reflecting life''s delicate interplay between balance and imbalance. The works feature undulating surfaces that create dynamic, shifting reflections, contrasted with crisp, almost flawless segments.', '[]', '["/images/projects/balancing_act/image_1.jpg","/images/projects/balancing_act/image_2.jpg","/images/projects/balancing_act/image_3.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('pool_of_dreams', 'pool-of-dreams', 'Pool of Dreams', 'Amsterdam Light Art Collection, Netherlands', 'https://www.vibhorsogani.com/work/pool-of-dreams', 'Pool of Dreams was created for the 12th edition of the Amsterdam Light Festival 2023. Now a part of the permanent portfolio of the Light Art Collection in Amsterdam, the installation features polished steel orbs that playfully rise from the water and spill onto the adjacent land. It has also been showcased in Aarhaus Festuge 2024, Denmark. (Photo credits: Janus Van Eijnden)', '[]', '["/images/projects/pool_of_dreams/image_1.jpg","/images/projects/pool_of_dreams/image_2.jpg","/images/projects/pool_of_dreams/image_3.png","/images/projects/pool_of_dreams/image_4.jpg","/images/projects/pool_of_dreams/image_5.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('kalpataru', 'kalpataru', 'Kalpataru', 'Motilal Nehru Marg, New Delhi, India', 'https://www.vibhorsogani.com/work/kalpataru', 'Created for Project PARI, Kalpataru is a 20-foot tall light art installation accomplished with the support of the Ministry of Culture, Government of India and the National Gallery of Modern Art. Inspired by the sacred tree from ancient mythology, Kalpataru stands as a symbol of abundance, prosperity, and the fulfilment of desires. The luminous form reflects India''s deep cultural roots while embodying its forward-looking spirit.', '[]', '["/images/projects/kalpataru/image_1.jpg","/images/projects/kalpataru/image_2.jpg","/images/projects/kalpataru/image_3.jpg","/images/projects/kalpataru/image_4.jpg","/images/projects/kalpataru/image_5.jpg","/images/projects/kalpataru/image_6.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('shankha', 'shankha', 'Shankha', 'Studio Collection & Private Sanctuaries', 'https://www.vibhorsogani.com/work/shankha', 'Inspired by the ''Shankha'' or conch shell, this piece encapsulates the essence of life and nature. In Hindu mythology, the Shankha signifies the beginning of any auspicious endeavour, its sound revered as the purest form that ushers in freshness and new hope. It symbolises purity, brilliance, and auspiciousness. The interior glows with a warm amber light.', '[]', '["/images/projects/shankha/image_1.jpg","/images/projects/shankha/image_2.jpg","/images/projects/shankha/image_3.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('thus_life', 'thus-life', 'Thus Life', 'Public Landmark, Gurgaon, India', 'https://www.vibhorsogani.com/work/thus-life', 'Thus Life, an Art Installation by Vibhor Sogani, embodies the evolutionary patterns found in ecological systems, where growth follows a definite rhythm, yet remains inherently fluid and dynamic. The form, inspired by bionics, draws from the principles of biology and natural science. Its curvature and flowing design evoke a sense of growth and progress.', '[]', '["/images/projects/thus_life/image_1.jpg","/images/projects/thus_life/image_2.jpeg","/images/projects/thus_life/image_3.jpeg","/images/projects/thus_life/image_4.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('nebula', 'nebula', 'Nebula', 'Dubai Design Week, Dubai, UAE', 'https://www.vibhorsogani.com/work/nebula', '"In the world where we may not constantly be accompanied by another, the NEBULA is a reminder that we do not run solo; instead, we carry within many versions of our own selves — because, we are never just one person." — Vibhor Sogani. Nebula, a suspended sculpture made from mirror-finished stainless-steel spheres, invites viewers to reflect on the multi-layered nature of human experience. Created for Dubai Design Week.', '[]', '["/images/projects/nebula/image_1.jpg","/images/projects/nebula/image_2.jpg","/images/projects/nebula/image_3.jpg","/images/projects/nebula/image_4.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('soldier_saint_poet', 'soldier-saint-poet', 'Soldier, Saint, Poet', 'Prakash Punj, Patna, Bihar, India', 'https://www.vibhorsogani.com/work/soldier-saint-poet', 'Soldier, Saint, Poet is a tribute to Guru Gobind Singh Ji. The art installation, made of brass and steel, was conceptualised by Arpana Caur and translated into form by Vibhor Sogani. It is located at Prakash Punj, Bihar, India.', '[]', '["/images/projects/soldier_saint_poet/image_1.jpg","/images/projects/soldier_saint_poet/image_2.jpg","/images/projects/soldier_saint_poet/image_3.jpg","/images/projects/soldier_saint_poet/image_4.jpg","/images/projects/soldier_saint_poet/image_5.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('magical_bloom', 'magical-bloom', 'Magical Bloom', 'Outdoor Art Showcase & Civic Plazas', 'https://www.vibhorsogani.com/work/magical-bloom', 'The light installation is made of countless polished stainless-steel orbs that come together to form the shape of a flower in full glory. Magical Bloom serves as a visual reminder of the boundless natural beauty around us. The reflective orbs interact with the environment, mirroring the ever-changing sky, people, and movements, creating a tapestry of sparkling, multi-layered reflections.', '[]', '["/images/projects/magical_bloom/image_1.jpg","/images/projects/magical_bloom/image_2.jpg","/images/projects/magical_bloom/image_3.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('rhythm', 'rhythm', 'Rhythm', 'Public & Corporate Atriums, India', 'https://www.vibhorsogani.com/work/rhythm', '"Music & Rhythm find their way into the secret places of our soul." In the performance arts, rhythm is the timing of events on a human scale; of musical sounds and silences that occur over time, of the steps of a dance, or the meter of unspoken language and poetry. The rhythm of life is felt when you experience your own body, mind, and soul together.', '[]', '["/images/projects/rhythm/image_1.jpg","/images/projects/rhythm/image_2.jpg","/images/projects/rhythm/image_3.JPG"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('a_slice_of_sky', 'a-slice-of-sky', 'A Slice of Sky', 'Architectural Waterscapes & Pavilions', 'https://www.vibhorsogani.com/work/a-slice-of-sky', 'A Slice of Sky takes the form of floating lotus petals. The soft metal curves gently, creating a space that sits harmoniously within the landscape. Mirror-finish droplets, like shimmering mercury, trickle down the satin surface and the mirrored water evokes a sense of serenity and wonder.', '[]', '["/images/projects/a_slice_of_sky/image_1.jpg","/images/projects/a_slice_of_sky/image_2.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('aroma', 'aroma', 'Aroma', 'Corporate Atrium, India', 'https://www.vibhorsogani.com/work/aroma', 'The light installation serves as the centrepiece of a 50-foot-high reception atrium for a leading spice manufacturing company. Suspended from the ceiling, the 35-foot-tall piece features mirror-finished stainless steel balls and floating ''aroma rings'' of light that spiral upward and expand.', '[]', '["/images/projects/aroma/image_1.jpg","/images/projects/aroma/image_2.jpg","/images/projects/aroma/image_3.jpg","/images/projects/aroma/image_4.jpg","/images/projects/aroma/image_5.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('divine_walk', 'divine-walk', 'Divine Walk', 'NGMA, New Delhi, India', 'https://www.vibhorsogani.com/work/divine-walk', 'Divine Walk was showcased as part of Chitrakavyam Ramayanam, an exhibition at the National Gallery of Modern Art, India. The exhibition featured artistic interpretations of the Ramayana, with Divine Walk offering a visual narrative for this timeless epic.', '[]', '["/images/projects/divine_walk/image_1.jpg","/images/projects/divine_walk/image_2.jpg","/images/projects/divine_walk/image_3.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('kink_within', 'kink-within', 'Kink Within', 'Studio Collection & Sculpture Biennales', 'https://www.vibhorsogani.com/work/kink-within', 'Kink Within refers in its design to a barren landscape, cracked and desolate. Even in these harsh terrains, small plants push through the ground. These resilient spurs symbolize the incredible spirit of living things. They adapt, thrive, and overcome obstacles.', '[]', '["/images/projects/kink_within/image_1.jpg","/images/projects/kink_within/image_2.jpg","/images/projects/kink_within/image_3.jpg","/images/projects/kink_within/image_4.JPG"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('casa', 'casa', 'Casa', 'Bespoke Architectural Installations', 'https://www.vibhorsogani.com/work/casa', 'Casa, a light installation inspired from the "weaver''s nest" is a tribute to home in the vast, natural world. Constructed with a blend of approximately 4500 SS mirror finished beads, it gives a sense of life within, with a warm glow. The ever changing, multiple reflections produce a visual texture that makes the cocoon form mesmerizing from all around.', '[]', '["/images/projects/casa/image_1.jpg","/images/projects/casa/image_2.jpg","/images/projects/casa/image_3.jpg","/images/projects/casa/image_4.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('blue_grass', 'blue-grass', 'Blue Grass', 'Light Art Exhibitions & Plazas', 'https://www.vibhorsogani.com/work/blue-grass', 'Blue Grass consists of a group of wavy stainless steel strands that undulate gracefully in a celebratory pattern. Each strand''s diameter gradually decreases from bottom to top, creating gaps filled with gentle blue glow.', '[]', '["/images/projects/blue_grass/image_1.jpg","/images/projects/blue_grass/image_2.jpg","/images/projects/blue_grass/image_3.jpg","/images/projects/blue_grass/image_4.png"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('life', 'life', 'Life', 'Gallery & Studio Collection', 'https://www.vibhorsogani.com/work/life', 'Crafted from stainless steel and copper, Life is an installation that explores how the smallest challenges have the power to shape and bend the narrative of our lives.', '[]', '["/images/projects/life/image_1.jpg","/images/projects/life/image_2.jpg","/images/projects/life/image_3.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('the_hub', 'the-hub', 'The Hub', 'Institutional Campus, India', 'https://www.vibhorsogani.com/work/the-hub', 'The Hub illustrates an Institute''s stature, reflecting its role in interpreting and disseminating knowledge. The mirror-finished steel orb suggests a core, concentrated with values and crucial data. The layered metal rings around the core rise to form an expanding network of information.', '[]', '["/images/projects/the_hub/image_1.jpg","/images/projects/the_hub/image_2.jpg","/images/projects/the_hub/image_3.jpg","/images/projects/the_hub/image_4.jpeg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('confluence', 'confluence', 'Confluence', 'Tech & Science Landmark Plazas', 'https://www.vibhorsogani.com/work/confluence', 'Confluence, a Light Art installation, celebrates the relationship of space, science, and technology and the intricacies involved in its application for complex human advancement. The sculpture is reminiscent of a receptacle that facilitates the give-gather-give cycle of information.', '[]', '["/images/projects/confluence/image_1.jpg","/images/projects/confluence/image_2.jpeg","/images/projects/confluence/image_3.jpeg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('quartz', 'quartz', 'Quartz', 'Studio Collection & Gallery Exhibitions', 'https://www.vibhorsogani.com/work/quartz', 'Quartz, an art installation.', '[]', '["/images/projects/quartz/image_1.jpg","/images/projects/quartz/image_2.jpg","/images/projects/quartz/image_3.jpg","/images/projects/quartz/image_4.jpg","/images/projects/quartz/image_5.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('mahatma_gandhi', 'mahatma-gandhi', 'Mahatma Gandhi', 'Cabinet Room, New Delhi, India', 'https://www.vibhorsogani.com/work/mahatma-gandhi', 'Mahatma Gandhi, Father of our nation. Location: Cabinet Room, New Delhi.', '[]', '["/images/projects/mahatma_gandhi/image_1.jpg","/images/projects/mahatma_gandhi/image_2.jpg","/images/projects/mahatma_gandhi/image_3.jpg","/images/projects/mahatma_gandhi/image_4.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('rooted_in_diversity', 'rooted-in-diversity', 'Rooted in Diversity', 'National Public Art Showcase, India', 'https://www.vibhorsogani.com/work/rooted-in-diversity', 'Rooted in Diversity — a celebration of unity within plurality.', '[]', '["/images/projects/rooted_in_diversity/image_1.jpg","/images/projects/rooted_in_diversity/image_2.jpg","/images/projects/rooted_in_diversity/image_3.png"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('enso', 'enso', 'Ensō', 'International Exhibitions & Zen Sanctuaries', 'https://www.vibhorsogani.com/work/enso', 'Ensō is one of the deepest symbols in Japanese Zen — the revelation of a world of the spirit without beginning and end. The artwork is a circle made of stainless steel spheres. It represents a fleeting moment when mind releases its grip and body is able to create freely.', '[]', '["/images/projects/enso/image_1.jpg","/images/projects/enso/image_2.jpg","/images/projects/enso/image_3.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('in_deep_thought', 'in-deep-thought', 'In Deep Thought', 'Australia, Mumbai & Zimbabwe', 'https://www.vibhorsogani.com/work/in-deep-thought', 'In Deep Thought — Mahatma in me. "A man is but a product of his thoughts. What he thinks, he becomes." — MK Gandhi. Gandhi was a firm believer in the power of thoughts to change one''s life and destiny. Exhibited in Australia, Mumbai, and Zimbabwe.', '[]', '["/images/projects/in_deep_thought/image_1.jpg","/images/projects/in_deep_thought/image_2.png","/images/projects/in_deep_thought/image_3.jpg","/images/projects/in_deep_thought/image_4.jpg","/images/projects/in_deep_thought/image_5.gif"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('a_legendary_smile', 'a-legendary-smile', 'A Legendary Smile', 'India, Australia & Africa', 'https://www.vibhorsogani.com/work/a-legendary-smile', 'A Legendary Smile — Mahatma in me. "One must be able to love the meanest of creation as oneself." — MK Gandhi. Gandhi''s legendary childlike smile was innocent, non-judgemental, and full of compassion, earning him the reputation of the Smiling Saint. Exhibited in India, Australia, and Africa.', '[]', '["/images/projects/a_legendary_smile/image_1.jpg","/images/projects/a_legendary_smile/image_2.JPG","/images/projects/a_legendary_smile/image_3.jpg","/images/projects/a_legendary_smile/image_4.jpg"]');
INSERT INTO projects (id, slug, title, location, url, description, paragraphs, images) VALUES ('autumn', 'autumn', 'Autumn', 'Wall Art Installations & Private Collections', 'https://www.vibhorsogani.com/work/autumn', 'Autumn, a wall art installation.', '[]', '["/images/projects/autumn/image_1.jpg","/images/projects/autumn/image_2.JPG","/images/projects/autumn/image_3.jpg","/images/projects/autumn/image_4.jpg"]');
